  "knowledge": "Engaged Lurker",
  "description": "A fan who actively consumes a large amount of content but participates minimally in social chat.",
  "definition": "A fan is an Engaged Lurker if their Content Consumption Index (CCI) is greater than 0.5 and their Chattiness Score (CS) is less than 0.5."
}

{
  "id": 1,
  "knowledge": "Content Consumption Index (CCI)",
  "description": "Quantifies a fan's level of passive engagement by measuring the hours of content they watch relative to their session time.",
  "definition": "CCI = \\frac{\\text{Total Watch Hours}}{\\text{Session Duration in Minutes}}"
}

{
  "id": 2,
  "knowledge": "Chattiness Score (CS)",
  "description": "Measures a fan's active communication during a session, reflecting their level of social interaction.",
  "definition": "CS = \\frac{\\text{Number of Chat Messages Sent}}{\\text{Session Duration in Minutes}}"
}

{
  "id": 3,
  "knowledge": "Fan Financial Value (FFV)",
  "description": "Estimates a fan's monthly financial contribution to the platform, serving as a proxy for their lifetime value.",
  "definition": "FFV = \\frac{\\text{Total Spending in USD}}{\\text{Membership Duration in Days} / 30.44}"
}

{
  "id": 0,
  "knowledge": "Fan Monetization Index (FMI)",
  "description": "Measures a fan's direct financial contribution per minute of engagement, indicating their propensity for in-session spending.",
  "definition": "FMI = \\frac{\\text{Total Gift Value in USD}}{\\text{Session Duration in Minutes}}"
}

{
  "id": 56,
  "knowledge": "Peak Monetization Index",
  "description": "The highest Fan Monetization Index (FMI) a fan has achieved in any single interaction session.",
  "definition": "The maximum value of the Fan Monetization Index (FMI) calculated across all of a fan's interaction sessions."
}

